export function fibonacci(n: number): number {
  let previous = 0;
  let current = 1;

  for (let i = 0; i < n; i++) {
    const next = previous + current;

    previous = current;
    current = next;
  }

  return previous;
}

export function fibonacci(n: number): number {
  if (n <= 1) return n;

  return fibonacci(n - 1) + fibonacci(n - 2);
}

